  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background: linear-gradient(135deg, #0a0e27 0%, #1a1f3a 100%);
  color: #e0e6ed;
  line-height: 1.6;
  min-height: 100vh;
  padding: 20px;
}

main {
  max-width: 800px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 60px;
}

h1 {
  font-size: 2.5rem;
  margin-bottom: 10px;
  background: linear-gradient(135deg, #60a5fa 0%, #a78bfa 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header p {
  color: #9ca3af;
  font-size: 1.1rem;
}

.faq-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.example {
  border: 1px solid #374151;
  border-radius: 12px;
  background: rgba(17, 24, 39, 0.6);
  backdrop-filter: blur(10px);
  transition: all 0.3s ease;
  overflow: hidden;
}

.example:hover {
  border-color: #4b5563;
  background: rgba(31, 41, 55, 0.8);
}

h2 {
  margin: 0;
}

.faq-trigger {
  width: 100%;
  padding: 20px 24px;
  background: none;
  border: none;
  color: #e0e6ed;
  font-size: 1.1rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: all 0.2s ease;
}

.faq-trigger:hover {
  color: #60a5fa;
  background: rgba(96, 165, 250, 0.05);
}

.faq-trigger:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: -2px;
  background: rgba(96, 165, 250, 0.1);
}

.faq-trigger::after {
  content: '';
  display: inline-block;
  width: 24px;
  height: 24px;
  margin-left: 16px;
  flex-shrink: 0;
  background: linear-gradient(135deg, #60a5fa 0%, #a78bfa 100%);
  -webkit-mask-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>');
  mask-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>');
  transition: transform 0.3s ease;
}

.faq-trigger[aria-expanded="true"]::after {
  transform: rotate(180deg);
}

.details {
  max-height: 500px;
  overflow: hidden;
  padding: 0 24px;
  border-top: 1px solid #374151;
  transition: all 0.3s ease;
}

.details[hidden] {
  max-height: 0;
  padding: 0 24px;
  border-top: none;
}

.details p {
  padding: 20px 0;
  color: #d1d5db;
  font-size: 0.95rem;
}

.details p:last-child {
  padding-bottom: 20px;
}

/* Responsive design */
@media (max-width: 600px) {
  h1 {
    font-size: 1.75rem;
  }

  header {
    margin-bottom: 40px;
  }

  header p {
    font-size: 1rem;
  }

  .faq-trigger {
    padding: 16px 16px;
    font-size: 1rem;
  }

  .details {
    padding: 0 16px;
  }

  .details p {
    padding: 16px 0;
    font-size: 0.9rem;
  }
}

/* Forced colors mode support */
@media (forced-colors: active) {
  .example {
    border-width: 2px;
  }

  .faq-trigger:focus-visible {
    outline-width: 3px;
  }

  .faq-trigger::after {
    background: none;
    forced-color-adjust: none;
  }
}
